1	export type Cell = [number, number];
2	
3	const key = ([x, y]: Cell): string => `${x},${y}`;
4	
5	const neighbours = ([x, y]: Cell): Cell[] => [
6	  [x - 1, y - 1],
7	  [x, y - 1],
8	  [x + 1, y - 1],
9	  [x - 1, y],
10	  [x + 1, y],
11	  [x - 1, y + 1],
12	  [x, y + 1],
13	  [x + 1, y + 1],
14	];
15	
16	const dedupe = (cells: Cell[]): Cell[] => [
17	  ...new Map(cells.map((cell) => [key(cell), cell])).values(),
18	];
19	
20	export function nextGeneration(liveCells: Cell[]): Cell[] {
21	  const liveKeys = new Set(liveCells.map(key));
22	  const isLive = (cell: Cell): boolean => liveKeys.has(key(cell));
23	  const liveNeighbourCount = (cell: Cell): number =>
24	    neighbours(cell).filter(isLive).length;
25	
26	  // A cell can only change state if it is live or touches a live cell.
27	  const candidates = dedupe(liveCells.flatMap((cell) => [cell, ...neighbours(cell)]));
28	
29	  return candidates.filter((cell) => {
30	    const count = liveNeighbourCount(cell);
31	    return count === 3 || (count === 2 && isLive(cell));
32	  });
33	}
34

1	import { describe, it, expect } from "vitest";
2	import { nextGeneration, type Cell } from "./game-of-life.js";
3	
4	// The order of cells in a generation carries no meaning, so compare as sorted sets.
5	const sorted = (cells: Cell[]): Cell[] =>
6	  [...cells].sort(([ax, ay], [bx, by]) => ax - bx || ay - by);
7	
8	describe("Game of Life - Next Generation", () => {
9	  // Simplest cases
10	  it("returns an empty grid for an empty grid — [] -> []", () => {
11	    expect(nextGeneration([])).toEqual([]);
12	  });
13	  it("kills a single lone cell (0 neighbors) — [(0,0)] -> []", () => {
14	    expect(nextGeneration([[0, 0]])).toEqual([]);
15	  });
16	
17	  // Rule 1 - Underpopulation (live cell with < 2 live neighbors dies)
18	  it("kills both cells of a horizontal pair, each having 1 neighbor — [(0,1),(1,1)] -> []", () => {
19	    expect(
20	      nextGeneration([
21	        [0, 1],
22	        [1, 1],
23	      ]),
24	    ).toEqual([]);
25	  });
26	
27	  // Rule 2 - Survival (live cell with 2 or 3 live neighbors lives on)
28	  it("keeps a live cell with exactly 2 live neighbors alive — (1,1) survives in [(0,1),(1,1),(2,1)]", () => {
29	    const result = nextGeneration([
30	      [0, 1],
31	      [1, 1],
32	      [2, 1],
33	    ]);
34	
35	    expect(sorted(result)).toEqual(
36	      sorted([
37	        [1, 0],
38	        [1, 1],
39	        [1, 2],
40	      ]),
41	    );
42	  });
43	  it("keeps a live cell with exactly 3 live neighbors alive — (1,1) survives in [(0,2),(1,2),(2,2),(1,1)]", () => {
44	    const result = nextGeneration([
45	      [0, 2],
46	      [1, 2],
47	      [2, 2],
48	      [1, 1],
49	    ]);
50	
51	    expect(sorted(result)).toEqual(
52	      sorted([
53	        [0, 2],
54	        [1, 2],
55	        [2, 2],
56	        [1, 1],
57	        [0, 1],
58	        [2, 1],
59	        [1, 3],
60	      ]),
61	    );
62	  });
63	
64	  // Rule 3 - Overpopulation (live cell with > 3 live neighbors dies)
65	  it("kills a live cell with 4 live neighbors — (1,1) dies in [(0,2),(1,2),(2,2),(1,1),(1,0)]", () => {
66	    const result = nextGeneration([
67	      [0, 2],
68	      [1, 2],
69	      [2, 2],
70	      [1, 1],
71	      [1, 0],
72	    ]);
73	
74	    expect(sorted(result)).toEqual(
75	      sorted([
76	        [0, 2],
77	        [1, 2],
78	        [2, 2],
79	        [1, 3],
80	      ]),
81	    );
82	    expect(result).not.toContainEqual([1, 1]);
83	  });
84	
85	  // Rule 4 - Reproduction (dead cell with exactly 3 live neighbors becomes alive)
86	  it("brings a dead cell with exactly 3 live neighbors to life — (1,1) becomes alive in [(0,2),(1,2),(0,1)]", () => {
87	    const result = nextGeneration([
88	      [0, 2],
89	      [1, 2],
90	      [0, 1],
91	    ]);
92	
93	    expect(result).toContainEqual([1, 1]);
94	    expect(sorted(result)).toEqual(
95	      sorted([
96	        [0, 2],
97	        [1, 2],
98	        [0, 1],
99	        [1, 1],
100	      ]),
101	    );
102	  });
103	  it("leaves a dead cell with 2 live neighbors dead — (1,1) stays dead in [(0,1),(2,1)]", () => {
104	    const result = nextGeneration([
105	      [0, 1],
106	      [2, 1],
107	    ]);
108	
109	    expect(result).not.toContainEqual([1, 1]);
110	    expect(result).toEqual([]);
111	  });
112	
113	  // Negative coordinates / infinite grid
114	  it("handles negative coordinates — block at [(-1,-1),(0,-1),(-1,0),(0,0)] is unchanged", () => {
115	    const block: Cell[] = [
116	      [-1, -1],
117	      [0, -1],
118	      [-1, 0],
119	      [0, 0],
120	    ];
121	
122	    expect(sorted(nextGeneration(block))).toEqual(sorted(block));
123	  });
124	
125	  // Patterns
126	  it("keeps the block still life unchanged — [(0,0),(1,0),(0,1),(1,1)] -> same 4 cells", () => {
127	    const block: Cell[] = [
128	      [0, 0],
129	      [1, 0],
130	      [0, 1],
131	      [1, 1],
132	    ];
133	
134	    expect(sorted(nextGeneration(block))).toEqual(sorted(block));
135	  });
136	  it("oscillates the blinker from vertical to horizontal — [(0,0),(0,1),(0,2)] -> [(-1,1),(0,1),(1,1)]", () => {
137	    const result = nextGeneration([
138	      [0, 0],
139	      [0, 1],
140	      [0, 2],
141	    ]);
142	
143	    expect(sorted(result)).toEqual(
144	      sorted([
145	        [-1, 1],
146	        [0, 1],
147	        [1, 1],
148	      ]),
149	    );
150	  });
151	  it("oscillates the blinker back to vertical after a second generation — [(-1,1),(0,1),(1,1)] -> [(0,0),(0,1),(0,2)]", () => {
152	    const gen0: Cell[] = [
153	      [0, 0],
154	      [0, 1],
155	      [0, 2],
156	    ];
157	
158	    const gen2 = nextGeneration(nextGeneration(gen0));
159	
160	    expect(sorted(gen2)).toEqual(sorted(gen0));
161	  });
162	});
